const request = $input.first().json;
return {
  json: {
    authorization: request.headers?.authorization || '',
    required_roles: ["admin", "c_level"],
    required_capability: "",
    request,
  },
};

const guard = $('Run Auth Guard').first().json;
if (!guard.ok) {
  return {
    json: {
      http_status: guard.status,
      body: { success: false, error: guard.code, message: guard.message },
    },
  };
}
const body = guard.request.body || guard.request;
const action = body.action;
if (action !== 'get' && action !== 'save' && action !== 'delete') {
  return {
    json: {
      http_status: 422,
      body: { success: false, error: 'INVALID_ACTION', message: 'Действие должно быть get, save или delete' },
    },
  };
}
// Writes are admin-only. The refusal fires by role, before the freeze check
// and before any SQL: hiding a button is not access control.
if (action !== 'get' && String(guard.identity.role || '') !== 'admin') {
  return {
    json: {
      http_status: 403,
      body: { success: false, error: 'ROLE_FORBIDDEN', message: 'Изменение критериев доступно только администратору' },
    },
  };
}
if (action === 'get') {
  return {
    json: {
      ok: true,
      mode: 'get',
      sql: `
        SELECT
          c.*,
          (
            SELECT json_build_object(
              'id', p.id,
              'name', p.name,
              'status', p.status,
              'is_active', p.is_active,
              'period_type', p.period_type,
              'start_date', p.start_date,
              'end_date', p.end_date,
              'evaluation_started_at', p.evaluation_started_at,
              'evaluation_started', (p.evaluation_started_at IS NOT NULL)
            )
            FROM performance_db.evaluation_periods p
            WHERE p.is_active = true AND p.status = 'active'
            LIMIT 1
          ) AS _period
        FROM performance_db.criteria c
        ORDER BY c.id ASC
      `,
    },
  };
}
// The catalogue freezes when the evaluation STARTS, not when the period is
// activated (D-0822-1). Draft and the preparation window are both editable.
return {
  json: {
    ok: true,
    mode: 'write',
    action,
    sql: `
      SELECT id, name, status
      FROM performance_db.evaluation_periods
      WHERE is_active = true
        AND status = 'active'
        AND evaluation_started_at IS NOT NULL
      LIMIT 1
    `,
  },
};

const prev = $('Route Action').first().json;
if (prev.http_status) {
  return { json: prev };
}
if (prev.mode === 'get') {
  const rows = $input.all().map(item => item.json).filter(item => item.id !== undefined);
  let periodRaw = rows.length ? rows[0]._period : null;
  if (typeof periodRaw === 'string') {
    try { periodRaw = JSON.parse(periodRaw); } catch (e) { periodRaw = null; }
  }
  const data = rows.map(row => {
    const copy = { ...row };
    delete copy._period;
    return copy;
  });
  const isActive = periodRaw && (periodRaw.is_active === true || periodRaw.is_active === 'true');
  const isStarted = Boolean(periodRaw && periodRaw.evaluation_started_at);
  return {
    json: {
      http_status: 200,
      body: {
        data,
        period: periodRaw
          ? {
              id: Number(periodRaw.id),
              name: periodRaw.name,
              status: periodRaw.status,
              is_active: Boolean(isActive),
              period_type: periodRaw.period_type,
              start_date: periodRaw.start_date,
              end_date: periodRaw.end_date,
              evaluation_started_at: periodRaw.evaluation_started_at || null,
              evaluation_started: isStarted,
            }
          : null,
        campaign_active: Boolean(isActive && periodRaw && periodRaw.status === 'active'),
        // Writes freeze on start, not on activation (D-0822-1).
        evaluation_started: Boolean(isActive && periodRaw && periodRaw.status === 'active' && isStarted),
      },
    },
  };
}
const startedPeriod = $input.all().map(item => item.json).find(item => item.id !== undefined);
if (startedPeriod) {
  return {
    json: {
      http_status: 409,
      body: {
        success: false,
        error: 'EVALUATION_STARTED',
        message: `Нельзя менять критерии: оценка в периоде «${startedPeriod.name}» уже идёт`,
      },
    },
  };
}
const guard = $('Run Auth Guard').first().json;
const body = guard.request.body || guard.request;
const item = body.criteria || {};
const action = prev.action;
// ЛОГИКА УДАЛЕНИЯ
if (action === 'delete') {
   return { 
    json: { 
      query: `DELETE FROM performance_db.criteria WHERE id = ${item.id} RETURNING id;` 
    } 
  };
}

// ЛОГИКА СОХРАНЕНИЯ (SAVE)
const safe = (str) => str ? str.toString().replace(/'/g, "''") : "";
const title = safe(item.title);
const desc = safe(item.description);
const aud = safe(item.target_audience);
const active = item.is_active ? 'TRUE' : 'FALSE';
const selfassesment = item.selfassesment !== undefined ? (item.selfassesment ? 'TRUE' : 'FALSE') : 'TRUE';
const forManager = item.for_manager !== undefined ? (item.for_manager ? 'TRUE' : 'FALSE') : 'TRUE';
const cLevelOnly = item.c_level_only !== undefined ? (item.c_level_only ? 'TRUE' : 'FALSE') : 'FALSE';

// Обработка level_*_desc полей (0-10)
const levels = {};
for (let i = 0; i <= 10; i++) {
  const fieldName = `level_${i}_desc`;
  levels[fieldName] = item[fieldName] ? safe(item[fieldName]) : null;
}

if (item.id) {
  // UPDATE существующего критерия
  const levelUpdates = [];
  for (let i = 0; i <= 10; i++) {
    const fieldName = `level_${i}_desc`;
    const value = levels[fieldName];
    if (value !== null) {
      levelUpdates.push(`${fieldName} = '${value}'`);
    } else {
      levelUpdates.push(`${fieldName} = NULL`);
    }
  }

  const query = `UPDATE performance_db.criteria SET 
    title = '${title}', 
    description = '${desc}', 
    target_audience = '${aud}', 
    is_active = ${active},
    selfassesment = ${selfassesment},
    for_manager = ${forManager},
    c_level_only = ${cLevelOnly},
    ${levelUpdates.join(', ')}
    WHERE id = ${item.id} RETURNING id;`;

  return { json: { query: query } };

} else {
  // INSERT нового критерия
  const levelFields = [];
  const levelValues = [];

  for (let i = 0; i <= 10; i++) {
    const fieldName = `level_${i}_desc`;
    levelFields.push(fieldName);
    const value = levels[fieldName];
    if (value !== null) {
      levelValues.push(`'${value}'`);
    } else {
      levelValues.push('NULL');
    }
  }

  const query = `INSERT INTO performance_db.criteria 
    (title, description, category, target_audience, is_active, selfassesment, for_manager, c_level_only, ${levelFields.join(', ')}) 
    VALUES 
    ('${title}', '${desc}', 'dynamic', '${aud}', ${active}, ${selfassesment}, ${forManager}, ${cLevelOnly}, ${levelValues.join(', ')}) 
    RETURNING id;`;

  return { json: { query: query } };
}

const prev = $('Prepare Write').first().json;
if (prev.http_status) {
  return { json: prev };
}
return {
  json: {
    http_status: 200,
    body: { success: true, message: 'Operation successful' },
  },
};
